import{_ as a,o as n,c as t,a0 as o}from"./chunks/framework.DCluYYrN.js";const u=JSON.parse('{"title":"x86_64 Support","description":"","frontmatter":{},"headers":[],"relativePath":"guide/x86_64-support.md","filePath":"guide/x86_64-support.md"}'),i={name:"guide/x86_64-support.md"};function s(r,e,c,l,p,h){return n(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="x86-64-support" tabindex="-1">x86_64 Support <a class="header-anchor" href="#x86-64-support" aria-label="Permalink to &quot;x86_64 Support&quot;">​</a></h1><p>KernelSU fully supports the <code>x86_64</code> architecture. However, due to recent upstream kernel security changes, integrating KernelSU on modern <code>x86_64</code> kernels requires additional handling so our unified syscall dispatcher can function correctly.</p><h2 id="why-did-it-break" tabindex="-1">Why did it break? <a class="header-anchor" href="#why-did-it-break" aria-label="Permalink to &quot;Why did it break?&quot;">​</a></h2><p>In newer kernel versions, a <a href="https://git.kernel.org/pub/scm/linux/kernel/git/stable/linux.git/commit/?id=1e3ad78334a69b36e107232e337f9d693dcc9df2" target="_blank" rel="noreferrer">commit</a> was introduced to harden the syscall table. This change converted indirect branches within the system call path into a series of direct conditional branches.</p><p>KernelSU&#39;s <code>syscall_hook</code> mechanism relies on modifying entries in the syscall table so intercepted system calls can be routed to our unified dispatcher. Because the new hardening changes the syscall path, the kernel ignores those syscall table modifications. If KernelSU attempts to load and hook the syscall table without handling this limitation correctly, it will fail to route the calls and cleanly abort initialization to prevent a kernel panic.</p><h2 id="how-to-fix-it" tabindex="-1">How to fix it? <a class="header-anchor" href="#how-to-fix-it" aria-label="Permalink to &quot;How to fix it?&quot;">​</a></h2><p>There are two supported ways to handle this syscall hook issue on <code>x86_64</code>:</p><ol><li>Enable the kernel build option <code>KSU_X86_PATCH_SYSCALL_DISPATCHER</code>.</li><li>Continue using the original kernel source patch method.</li></ol><p>You only need to use one of them. Do not apply both at the same time.</p><h3 id="option-1-enable-ksu-x86-patch-syscall-dispatcher" tabindex="-1">Option 1: Enable <code>KSU_X86_PATCH_SYSCALL_DISPATCHER</code> <a class="header-anchor" href="#option-1-enable-ksu-x86-patch-syscall-dispatcher" aria-label="Permalink to &quot;Option 1: Enable \`KSU_X86_PATCH_SYSCALL_DISPATCHER\`&quot;">​</a></h3><p>KernelSU 3.3.0 introduced an official mechanism for <code>x86_64</code>: the build option <code>KSU_X86_PATCH_SYSCALL_DISPATCHER</code>.</p><p>When this option is enabled, KernelSU dynamically patches the hardened syscall dispatcher at runtime so the syscall hook can work without requiring the previous kernel source patch set. This is the recommended approach if you are building a kernel with KernelSU 3.3.0 or newer.</p><h3 id="option-2-apply-the-original-kernel-source-patches" tabindex="-1">Option 2: Apply the original kernel source patches <a class="header-anchor" href="#option-2-apply-the-original-kernel-source-patches" aria-label="Permalink to &quot;Option 2: Apply the original kernel source patches&quot;">​</a></h3><p>If you do not want to enable <code>KSU_X86_PATCH_SYSCALL_DISPATCHER</code>, you can continue to use the original kernel patch approach.</p><p>To make KernelSU work on these newer kernels, apply a patch that allows you to bypass this specific syscall hardening.</p><div class="danger custom-block"><p class="custom-block-title">SECURITY WARNING</p><p>By using either of these two solutions, you are intentionally bypassing or weakening a mitigation designed to protect against speculative execution vulnerabilities.</p><p>This re-opens the indirect branch attack surface for system calls. <strong>Do not use either solution if you are running a production server or a system where strict side-channel security is critical.</strong> These approaches are intended for testing environments where root access via KernelSU is prioritized over this specific hardware vulnerability mitigation.</p></div><p>Choose and apply the patches that match your kernel version below. These patches create a feature called <code>X86_FEATURE_INDIRECT_SAFE</code> and can be activated using the kernel cmdline <code>syscall_hardening=off</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>For kernel 6.6:</span></span>
<span class="line"><span>https://github.com/android-generic/kernel_common/commit/fe9a9b4c320577c30e1f22d04039e414c6a3cdec</span></span>
<span class="line"><span>https://github.com/android-generic/kernel_common/commit/df772e99e392f24b395ceaf7b26974e3e4828ee9</span></span>
<span class="line"><span></span></span>
<span class="line"><span>For kernel 6.12:</span></span>
<span class="line"><span>https://github.com/android-generic/kernel-zenith/commit/dd2c602268fdc81f4d3b662f6a15142ac0ec7bcd</span></span>
<span class="line"><span>https://github.com/android-generic/kernel-zenith/commit/7d99237ae5da61c19447138da3282ae37d43857b</span></span>
<span class="line"><span></span></span>
<span class="line"><span>For kernel 6.18:</span></span>
<span class="line"><span>https://github.com/android-generic/kernel-zenith/commit/40b1c323d1ad29c86e041d665c7f089b9a3ccfb5</span></span>
<span class="line"><span>https://github.com/android-generic/kernel-zenith/commit/f5813e10b7630e1ccd86fc2c4cf30eef60b64a82</span></span></code></pre></div><h2 id="which-method-should-i-choose" tabindex="-1">Which method should I choose? <a class="header-anchor" href="#which-method-should-i-choose" aria-label="Permalink to &quot;Which method should I choose?&quot;">​</a></h2><ul><li>If you are using KernelSU 3.3.0 or newer and can change the KernelSU build configuration, enable <code>KSU_X86_PATCH_SYSCALL_DISPATCHER</code>.</li><li>If you prefer to keep your current kernel-side patch workflow, continue using the original source patches above.</li></ul>`,20)])])}const m=a(i,[["render",s]]);export{u as __pageData,m as default};
